# BAD PATTERN (Shell Form - Breaks Signal Forwarding):
# CMD npm start  <-- Spawns /bin/sh -c 'npm start'; signals are trapped by /bin/sh!

# GOOD PATTERN 1: Exec Form (Direct Execution as PID 1)
FROM node:20-alpine
WORKDIR /app
COPY package*.json ./
RUN npm ci --omit=dev
COPY . .

# Exec form uses JSON array syntax:
CMD ["node", "server.js"]

